// Extrai o array de data stores da resposta
const response = $input.first().json;
const tables = response.data || response;

if (!Array.isArray(tables) || tables.length === 0) {
  throw new Error('Nenhuma Data Table encontrada.');
}

// Retorna um item por tabela para o loop
return tables.map(table => ({
  json: {
    tableId:    table.id,
    tableName:  table.name,
    n8nUrl:     $('Edit Fields - Variaveis').first().json.n8nUrl,
    n8nApiKey:  $('Edit Fields - Variaveis').first().json.n8nApiKey,
    username:   $('Edit Fields - Variaveis').first().json.username,
    token:      $('Edit Fields - Variaveis').first().json.token,
    repositorio:$('Edit Fields - Variaveis').first().json.repositorio,
    nome:       $('Edit Fields - Variaveis').first().json.nome,
    email:      $('Edit Fields - Variaveis').first().json.email
  }
}));

const tableId    = $('Code - Mapear Tabelas').item.json.tableId;
const tableName  = $('Code - Mapear Tabelas').item.json.tableName;
const repositorio= $('Code - Mapear Tabelas').item.json.repositorio;
const username   = $('Code - Mapear Tabelas').item.json.username;
const token      = $('Code - Mapear Tabelas').item.json.token;
const nome       = $('Code - Mapear Tabelas').item.json.nome;
const email      = $('Code - Mapear Tabelas').item.json.email;

const response = $input.first().json;
const rows = response.data || response;

// Sanitiza nome para uso como nome de arquivo
const safeName = tableName.replace(/[^a-zA-Z0-9_\-]/g, '_');

// Constrói JSON
const jsonContent = JSON.stringify(
  { tableName, tableId, totalRows: rows.length, rows },
  null, 2
);

// Constrói CSV
let csvContent = '';
if (rows.length > 0) {
  const keys = Object.keys(rows[0]);
  csvContent += keys.join(',') + '\n';
  rows.forEach(row => {
    const values = keys.map(k => {
      const v = row[k];
      if (v === null || v === undefined) return '';
      const s = String(v);
      return s.includes(',') || s.includes('"') || s.includes('\n')
        ? '"' + s.replace(/"/g, '""') + '"'
        : s;
    });
    csvContent += values.join(',') + '\n';
  });
} else {
  csvContent = 'vazio\n';
}

return [{ json: {
  tableId, tableName, safeName, repositorio,
  username, token, nome, email,
  jsonContent, csvContent,
  totalRows: rows.length
}}];
